<?php
require_once 'db.php'; require_once 'auth.php';
start_auth_session(); if (!empty($_SESSION['user_id'])) { header('Location: index.php'); exit; }
$loginError=null; $registerErrors=[]; $registerName=''; $registerEmail=''; $mode=($_GET['mode']??'')==='register'?'register':'login';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf($_POST['csrf']??null); $action=$_POST['action']??'login'; if($action==='login'){ $stmt=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1'); $stmt->execute([trim($_POST['email']??'')]); $user=$stmt->fetch(); if($user&&password_verify($_POST['password']??'',$user['password'])){session_regenerate_id(true);$_SESSION['user_id']=$user['id'];$_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role']??'user'];header('Location: '.(($user['role']??'user')==='admin'?'admin.php':'index.php'));exit; } else { $mode='register';$registerName=trim($_POST['name']??'');$registerEmail=trim($_POST['email']??'');$password=$_POST['password']??'';$confirm=$_POST['password_confirmation']??'';if($registerName==='')$registerErrors[]='Name is required.';if(!filter_var($registerEmail,FILTER_VALIDATE_EMAIL))$registerErrors[]='Enter a valid email address.';if(strlen($password)<8)$registerErrors[]='Password must be at least 8 characters.';if($password!==$confirm)$registerErrors[]='Passwords do not match.';$check=$pdo->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$check->execute([$registerEmail]);if($check->fetch())$registerErrors[]='That email is already registered.';if(!$registerErrors){$stmt=$pdo->prepare('INSERT INTO users (name,email,password) VALUES (?,?,?)');$stmt->execute([$registerName,$registerEmail,password_hash($password,PASSWORD_DEFAULT)]);header('Location: login.php?registered=1');exit;}}}}
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aisu Vault - Access</title><link rel="stylesheet" href="style.css"></head><body><div class="app auth-page"><section class="auth-intro"><span class="eyebrow">Aisu Vault</span><h1>Your records,<br><strong>beautifully organized.</strong></h1><p>Securely manage your documents and files in one calm workspace.</p></section><section class="auth-card"><div class="auth-tabs"><button type="button" data-mode="login" class="auth-tab <?= $mode==='login'?'active':'' ?>">Sign in</button><button type="button" data-mode="register" class="auth-tab <?= $mode==='register'?'active':'' ?>">Create account</button></div><div id="loginPanel" class="auth-panel" <?= $mode==='register'?'hidden':'' ?>><h2>Welcome back</h2><p class="auth-subtitle">Sign in to continue to your vault.</p><?php if($loginError): ?><div class="alert alert-error"><?=htmlspecialchars($loginError)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="login"><div class="form-group"><label for="login-email">Email</label><input id="login-email" name="email" type="email" required></div><div class="form-group"><label for="login-password">Password</label><input id="login-password" name="password" type="password" required></div><button class="button button-primary auth-submit" type="submit">Sign in</button></form></div><div id="registerPanel" class="auth-panel" <?= $mode==='login'?'hidden':'' ?>><h2>Create your account</h2><p class="auth-subtitle">Start organizing your records today.</p><?php if($registerErrors): ?><div class="alert alert-error"><ul><?php foreach($registerErrors as $error): ?><li><?=htmlspecialchars($error)?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="register"><div class="form-group"><label for="register-name">Name</label><input id="register-name" name="name" value="<?=htmlspecialchars($registerName)?>" required></div><div class="form-group"><label for="register-email">Email</label><input id="register-email" name="email" type="email" value="<?=htmlspecialchars($registerEmail)?>" required></div><div class="form-group"><label for="register-password">Password</label><input id="register-password" name="password" type="password" minlength="8" required></div><div class="form-group"><label for="register-confirm">Confirm password</label><input id="register-confirm" name="password_confirmation" type="password" minlength="8" required></div><button class="button button-primary auth-submit" type="submit">Create account</button></form></div></section></div><script>document.querySelectorAll('.auth-tab').forEach(tab=>tab.addEventListener('click',()=>{const register=tab.dataset.mode==='register';document.querySelectorAll('.auth-tab').forEach(x=>x.classList.toggle('active',x===tab));document.querySelector('#loginPanel').hidden=register;document.querySelector('#registerPanel').hidden=!register;}));</script></body></html>
